import React from 'react';
import { ISaleReturnDetailsData } from '../../core/Interface/saleReturn.interface';
import { ColumnDef } from '@tanstack/react-table';
import { formatDate, getPriceFormat } from '../../core/utils';
import { Box } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

const useReturnDetailsColumn = ({ currencyCode }: { currencyCode: string }) => {
  const { t } = useTranslation(['returnList']);

  const formatDateTime = (dateTime: string) => {
    const dateObj = new Date(dateTime);
    const time = dateObj.toLocaleTimeString();
    return { time };
  };

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
      cell: ({ row, table }) => {
        const pageIndex = table.getState().pagination.pageIndex;
        const pageSize = table.getState().pagination.pageSize;
        return <div>{pageIndex * pageSize + row.index + 1}</div>;
      },
    },
    {
      accessorKey: 'invoiceId',
      header: t('returnList:invoiceId'),
      size: 180,
      cell: (cell) => (
        <Link
          state={{ from: 'return-list' }}
          to={`/sales-return/${cell.row.original.saleId}`}
        >
          {cell.row.original.invoiceId}
        </Link>
      ),
    },
    {
      accessorKey: 'dateTime',
      header: t('returnList:date'),
      size: 180,
      id: 'Date',
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'left' }}>
            {formatDate(new Date(cell.row.original.dateTime))}
          </Box>
        );
      },
    },
    {
      accessorKey: 'dateTime',
      header: (
        <div style={{ textAlign: 'justify' }}>{t('returnList:time')}</div>
      ),
      size: 180,
      id: 'Time',
      cell: (cell) => {
        const { time } = formatDateTime(cell.row.original.dateTime);
        return <Box sx={{ textAlign: 'justify', height: 30 }}>{time}</Box>;
      },
    },
    {
      accessorKey: 'returnAmount',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('returnList:returnAmount')}</Box>
      ),
      size: 180,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {getPriceFormat(cell.row.original.returnAmount, currencyCode)}
          </Box>
        );
      },
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<ISaleReturnDetailsData>[];
};

export default useReturnDetailsColumn;
