import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import React, { CSSProperties, useMemo, useState } from 'react';
import { IUserInfo } from '../../core/Interface/user.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllReturnQuery, useGetUserQuery } from '../posApi';
import useReturnDetailsColumn from './useReturnDetailsColumn';
import { ISaleReturnDetails, ISaleReturnDetailsData } from '../../core/Interface/saleReturn.interface';

const useReturnDetails = () => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const {
    data: ReturnSaleDetailsData,
    isLoading,
    isFetching,
    error,
  } = useGetAllReturnQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const ReturnSaleDetailsMemo = useMemo(() => {
    return ReturnSaleDetailsData?.data as ISaleReturnDetails;
  }, [ReturnSaleDetailsData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return (
      ReturnSaleDetailsMemo?.records.filter((record) => {
        const code = record.invoiceId?.toLowerCase() || '';
        return code.includes(text);
      }) ?? []
    );
  }, [ReturnSaleDetailsMemo, searchText]);

  const columns = useReturnDetailsColumn({ currencyCode: currencyCode });

  const table = useReactTable({
    data: error ? [] : filteredData,
    meta: {
      getRowStyles: (row: Row<ISaleReturnDetailsData>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: ReturnSaleDetailsMemo?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: ReturnSaleDetailsMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useReturnDetails;
